/// Analysis (whitening) filter, upward: `e[n] = x[n] + Σ aₖ·x[n−k]`.
/// f64 accumulator, fixed op order. `a` is at most [`MAX_ORDER`] taps.
pub(super) fn analysis_filter(x: &mut [f32], orig: &[f32], a: &[f64]) {
    let n = x.len();
    let order = a.len().min(MAX_ORDER);
    let mut ak = [0.0f64; MAX_ORDER];
    ak[..order].copy_from_slice(&a[..order]);
    match order {
        0 => {
            for (slot, &s) in x.iter_mut().zip(orig.iter()).take(n) {
                *slot = f64::from(s) as f32;
            }
        }
        1 => fir::<1>(x, orig, &ak),
        2 => fir::<2>(x, orig, &ak),
        3 => fir::<3>(x, orig, &ak),
        4 => fir::<4>(x, orig, &ak),
        5 => fir::<5>(x, orig, &ak),
        6 => fir::<6>(x, orig, &ak),
        7 => fir::<7>(x, orig, &ak),
        8 => fir::<8>(x, orig, &ak),
        9 => fir::<9>(x, orig, &ak),
        10 => fir::<10>(x, orig, &ak),
        11 => fir::<11>(x, orig, &ak),
        _ => fir::<12>(x, orig, &ak),
    }
}

fn fir<const ORDER: usize>(x: &mut [f32], orig: &[f32], ak: &[f64; MAX_ORDER]) {
    let n = x.len().min(orig.len());
    let head = ORDER.min(n);
    for i in 0..head {
        let mut e = f64::from(orig[i]);
        for j in 0..i {
            e += ak[j] * f64::from(orig[i - 1 - j]);
        }
        x[i] = e as f32;
    }
    let mut i = head;
    // Every output depends on the original samples only. Parallel outputs
    // retain each sample's coefficient/add order without shifting history.
    while i + 4 <= n {
        let mut e = [
            f64::from(orig[i]),
            f64::from(orig[i + 1]),
            f64::from(orig[i + 2]),
            f64::from(orig[i + 3]),
        ];
        for (j, &a) in ak.iter().enumerate().take(ORDER) {
            let p = i - 1 - j;
            e[0] += a * f64::from(orig[p]);
            e[1] += a * f64::from(orig[p + 1]);
            e[2] += a * f64::from(orig[p + 2]);
            e[3] += a * f64::from(orig[p + 3]);
        }
        for (slot, value) in x[i..i + 4].iter_mut().zip(e) {
            *slot = value as f32;
        }
        i += 4;
    }
    for i in i..n {
        let mut e = f64::from(orig[i]);
        for (j, &a) in ak.iter().enumerate().take(ORDER) {
            e += a * f64::from(orig[i - 1 - j]);
        }
        x[i] = e as f32;
    }
}

