    #[inline(always)]
    pub fn peek_u32(&mut self, n: u32) -> Result<u32> {
        if n == 0 {
            return Ok(0);
        }
        if n > 32 {
            return Err(Error::Format("bit read wider than 32"));
        }
        if self.ncache < n {
            self.refill();
            if self.ncache < n {
                return Err(Error::UnexpectedEnd);
            }
        }
        Ok((self.cache >> (64 - n)) as u32)
    }

    /// Alias of [`Self::skip`].
    #[cfg(test)]
    pub fn consume(&mut self, n: u32) -> Result<()> {
        self.skip(n)
    }

