    pub fn skip(&mut self, n: u32) -> Result<()> {
        if self.bits_remaining() < u64::from(n) {
            return Err(Error::UnexpectedEnd);
        }
        let mut left = n;
        if left <= self.ncache {
            self.cache <<= left;
            self.ncache -= left;
            return Ok(());
        }
        left -= self.ncache;
        self.cache = 0;
        self.ncache = 0;
        self.byte_pos += (left / 8) as usize;
        left %= 8;
        if left > 0 {
            self.refill();
            self.cache <<= left;
            self.ncache -= left;
        }
        Ok(())
    }

