    pub fn byte_align(&mut self) -> Result<()> {
        let rem = (self.bit_position() % 8) as u32;
        if rem != 0 {
            self.skip(8 - rem)?;
        }
        Ok(())
    }
}

/// MSB-first writer used to build LC / SBR test frames.
#[derive(Default)]
pub struct BitWriter {
    buf: Vec<u8>,
    acc: u8,
    bits: u8,
}

impl BitWriter {
    /// Empty writer.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Reuse `buf` capacity (cleared). TASK-78 encoder payload recycle.
    #[must_use]
    pub fn from_vec(mut buf: Vec<u8>) -> Self {
        buf.clear();
        Self {
            buf,
            acc: 0,
            bits: 0,
        }
    }

    /// Append the low `n` bits of `value`, MSB first.
    #[inline]
    pub fn write(&mut self, value: u32, n: u32) {
        if n == 0 {
            return;
        }
        if n > 32 {
            self.write_wide(value, n);
            return;
        }
        let mut left = n;
        if self.bits > 0 {
            let take = left.min(u32::from(8 - self.bits));
            let part = ((value >> (left - take)) & ((1 << take) - 1)) as u8;
            self.acc = (self.acc << take) | part;
            self.bits += take as u8;
            left -= take;
            if self.bits < 8 {
                return;
            }
            self.buf.push(self.acc);
            self.acc = 0;
            self.bits = 0;
        }
        while left >= 8 {
            left -= 8;
            self.buf.push((value >> left) as u8);
        }
        if left > 0 {
            self.acc = value as u8 & ((1u8 << left) - 1);
            self.bits = left as u8;
        }
    }

    // Preserve the previous per-bit behavior outside the u32 field width,
    // including checked-shift failures, rather than inventing wider fields.
    #[cold]
    fn write_wide(&mut self, value: u32, n: u32) {
        for i in (0..n).rev() {
            let bit = ((value >> i) & 1) as u8;
            self.acc = (self.acc << 1) | bit;
            self.bits += 1;
            if self.bits == 8 {
                self.buf.push(self.acc);
                self.acc = 0;
                self.bits = 0;
            }
        }
    }

    /// Alias of [`Self::write`].
    pub fn write_u32(&mut self, value: u32, n: u32) {
        self.write(value, n)
    }

    /// Append one bit.
    #[inline]
    pub fn write_bit(&mut self, bit: bool) {
        self.acc = (self.acc << 1) | u8::from(bit);
        self.bits += 1;
        if self.bits == 8 {
            self.buf.push(self.acc);
            self.acc = 0;
            self.bits = 0;
        }
    }

    /// Bits written so far (before the final byte-align pad).
    #[must_use]
    pub fn bit_len(&self) -> u64 {
        (self.buf.len() as u64) * 8 + u64::from(self.bits)
    }

    /// Pad with zeros to a byte boundary and return the bytes.
    #[must_use]
    pub fn finish(mut self) -> Vec<u8> {
        if self.bits > 0 {
            self.acc <<= 8 - self.bits;
            self.buf.push(self.acc);
        }
        self.buf
    }
}

